case 'tiktokplay': {
 if (!isRegistered(m.sender) && !isCreator) return Reply(global.mess.verifikasi);

 if (checkLimit(m.sender, global.isPrem(m.sender), isCreator)) return Reply(global.mess.limit);

 if (!text) {
 return Reply(example("jj luser"))
 }

 addLimit(m.sender, global.isPrem(m.sender), isCreator);
 await alip.sendMessage(m.chat, { react: { text: "⏳", key: m.key } });
 Reply(mess.wait);

 const isPTVMode = command === 'ptv';
 const tmpDir = './tmp';
 if (!fs.existsSync(tmpDir)) fs.mkdirSync(tmpDir, { recursive: true });

 let tempFile = null;

 try {
 const query = encodeURIComponent(text.trim());
 const apiUrl = `https://api.nexray.eu.cc/search/tiktok?q=${query}`;

 const response = await axios.get(apiUrl, { timeout: 30000 });
 const data = response.data;

 if (!data.status || !data.result || data.result.length === 0) {
 await alip.sendMessage(m.chat, { react: { text: "❌", key: m.key } });
 return Reply(`❌ Video tidak ditemukan untuk *${text.trim()}*.`);
 }

 const firstVideo = data.result[Math.floor(Math.random() * data.result.length)];
 const videoUrl = firstVideo.data;

 if (!videoUrl) {
 await alip.sendMessage(m.chat, { react: { text: "❌", key: m.key } });
 return Reply(`❌ Link video tidak tersedia dari server.`);
 }

 const title = firstVideo.title || 'TikTok Video';

 tempFile = path.join(tmpDir, `tiktok_${Date.now()}.mp4`);

 const videoResponse = await axios({
 method: 'GET',
 url: videoUrl,
 responseType: 'stream',
 timeout: 60000,
 headers: {
 'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36',
 'Referer': 'https://www.tiktok.com/'
 }
 });

 const writer = fs.createWriteStream(tempFile);
 videoResponse.data.pipe(writer);

 await new Promise((resolve, reject) => {
 writer.on('finish', resolve);
 writer.on('error', reject);
 });

 const stat = fs.statSync(tempFile);
 if (!stat.size || stat.size < 1024) {
 throw new Error(`File video kosong/rusak (size: ${stat.size} bytes)`);
 }

 const videoBuffer = fs.readFileSync(tempFile);

 if (isPTVMode) {
 await alip.sendMessage(m.chat, {
 video: videoBuffer,
 ptv: true,
 mimetype: 'video/mp4'
 }, { quoted: m });
 } else {
 const caption = `${title.substring(0, 60)}${title.length > 60 ? '...' : ''}`;

 await alip.sendMessage(m.chat, {
 video: videoBuffer,
 mimetype: 'video/mp4',
 caption: caption
 }, { quoted: m });
 }

 fs.unlinkSync(tempFile);
 tempFile = null;
 await alip.sendMessage(m.chat, { react: { text: "✅", key: m.key } });

 } catch (error) {
 await alip.sendMessage(m.chat, { react: { text: "❌", key: m.key } });
 console.error("PLAYTIKTOK ERROR:", error.message || error);
 if (tempFile && fs.existsSync(tempFile)) {
 try { fs.unlinkSync(tempFile); } catch (e) {}
 }
 Reply(`❌ Gagal ambil video TikTok.\n_${error.message || 'Terjadi kesalahan'}_`);
 }
}
break;
